// Per-machine busy flag: machine_busy_<machineId>
// machineId comes from ?machine= query param (set by smia_machine_agent_services.py).
// Falls back to 'default' for old machine AASXs that do not yet include ?machine= in the pick href.
const DEFAULT_POSITION = 0;
const body   = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const query  = (msg.req && msg.req.query) ? msg.req.query : {};

const machineId = query.machine || 'default';
const busyKey   = 'machine_busy_' + machineId;
global.set(busyKey, true);

let posRaw = body.position;
if (posRaw === undefined || posRaw === null || posRaw === '') posRaw = query.position;
if ((posRaw === undefined || posRaw === null || posRaw === '') && DEFAULT_POSITION !== null) {
    posRaw = DEFAULT_POSITION;
}
if (posRaw === undefined || posRaw === null || posRaw === '') {
    global.set(busyKey, false);
    const errMsg = { ...msg, req: msg.req, res: msg.res, statusCode: 400,
                     payload: { status: 'error', reason: 'Missing field: position' } };
    return [null, errMsg, null];
}
const pos = Number(posRaw);
if (!Number.isInteger(pos) || pos < 0 || pos > 8) {
    global.set(busyKey, false);
    const errMsg = { ...msg, req: msg.req, res: msg.res, statusCode: 400,
                     payload: { status: 'error', reason: 'position must be integer 0..8' } };
    return [null, errMsg, null];
}

const mqttMsg  = { ...msg, topic: 'vicom/61/piso_0/lab/lego/commands',
                   payload: `bandera_custom:${pos}` };
const httpMsg  = { ...msg, req: msg.req, res: msg.res, statusCode: 200,
                   payload: { status: 'ok', payload: `bandera_custom:${pos}`, position: pos } };
// chainMsg carries machineId so the 8s delay chain clears the correct flag
const chainMsg = { payload: { action: 'pick', position: pos, machine: machineId } };

return [mqttMsg, httpMsg, chainMsg];

// Publishes busy status to MQTT visibility topic immediately
// msg.payload comes as { action: 'pick'|'place', position: N, machine: 'machineId' }
const info  = msg.payload;
msg.topic   = 'vicom/61/piso_0/lab/lego/status';
msg.payload = JSON.stringify({ status: 'busy', action: info.action, position: info.position, machine: info.machine });
return msg;

// Called 8 s after pick/place starts — releases the machine for new requests.
// msg.payload carries { machine: 'machineId' } from the chain originating in pick/place_handler.
const info      = msg.payload || {};
const machineId = info.machine || 'default';
const busyKey   = 'machine_busy_' + machineId;
global.set(busyKey, false);
msg.topic   = 'vicom/61/piso_0/lab/lego/status';
msg.payload = JSON.stringify({ status: 'available', machine: machineId });
return msg;

// Per-machine busy flag — same pattern as pick_handler.
const body  = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const query = (msg.req && msg.req.query) ? msg.req.query : {};

const machineId = query.machine || 'default';
const busyKey   = 'machine_busy_' + machineId;
global.set(busyKey, true);

let posRaw = body.position;
if (posRaw === undefined || posRaw === null || posRaw === '') posRaw = query.position;
if (posRaw === undefined || posRaw === null || posRaw === '') {
    global.set(busyKey, false);
    const errMsg = { ...msg, req: msg.req, res: msg.res, statusCode: 400,
                     payload: { status: 'error', reason: 'Missing field: position' } };
    return [null, errMsg, null];
}
const pos = Number(posRaw);
if (!Number.isInteger(pos) || pos < 0 || pos > 8) {
    global.set(busyKey, false);
    const errMsg = { ...msg, req: msg.req, res: msg.res, statusCode: 400,
                     payload: { status: 'error', reason: 'position must be integer 0..8' } };
    return [null, errMsg, null];
}

const mqttMsg  = { ...msg, topic: 'vicom/61/piso_0/lab/lego/commands',
                   payload: `bandera_place:${pos}` };
const httpMsg  = { ...msg, req: msg.req, res: msg.res, statusCode: 200,
                   payload: { status: 'ok', payload: `bandera_place:${pos}`, position: pos } };
const chainMsg = { payload: { action: 'place', position: pos, machine: machineId } };

return [mqttMsg, httpMsg, chainMsg];

// Returns plain-text '1.0' (free) or '0.0' (busy).
// smia_machine_agent_services.get_machine_availability() calls float(text.strip()).
// Per-machine flag: machine_busy_<machineId> — keyed by ?machine= query param.
// Falls back to 'default' for backward compatibility with AASXs without ?machine= in pick href.
const query     = (msg.req && msg.req.query) ? msg.req.query : {};
const machineId = query.machine || 'default';
const busyKey   = 'machine_busy_' + machineId;
const busy      = global.get(busyKey) || false;
msg.statusCode  = 200;
msg.headers     = { 'Content-Type': 'text/plain' };
msg.payload     = busy ? '0.0' : '1.0';
return msg;
